ion.customClass.length > 4) {\\n            stepStation.customClass.splice(4, stepStation.customClass.length - 4);\\n        }\\n        stepStationSup.addCssClass('hidden');\\n    }\\n\\n    //***********绑定工位号-激活步骤开始****************//\\n    //1、stepStation组件绑定\\n        //实际已走步骤数组\\n        let stepStationArr = res[0].eventRecordList.concat(res[1].eventRecordList).concat(res[2].eventRecordList);\\n        //实际已走步骤去重后数组\\n        let stepStationArrDis = [];\\n        for (let j = 0; j < stepStationArr.length; j++) {\\n            if (!stepStationArrDis.some(e => e.deviceNo == stepStationArr[j].deviceNo)) stepStationArrDis.push(stepStationArr[j]);\\n        }\\n        //根据实际已走步骤去重后数组绑定激活步骤\\n        debugger;\\n        for (let l = 0; l < stepStationArrDis.length; l++)\\n        {\\n            var stepArr = stepStation.widget.options.steps;\\n            const index = stepArr.findIndex(item => Number(item.title) === stepStationArrDis[l].deviceNo);\\n            if (index >= 0)\\n            {\\n                stepStation.widget.options.steps[index].status = 'finish';\\n            }\\n        }\\n\\n    //2、stepStationSup组件绑定\\n        //实际已走步骤数组\\n        let stepStationSupArr = res[3].eventRecordList.concat(res[4].eventRecordList);\\n        //实际已走步骤去重后数组\\n        let stepStationSupArrDis = [];\\n        for (let j = 0; j < stepStationSupArr.length; j++) {\\n            if (!stepStationSupArrDis.some(e => e.deviceNo == stepStationSupArr[j].deviceNo)) stepStationSupArrDis.push(stepStationSupArr[j]);\\n        }\\n        //根据实际已走步骤去重后数组绑定激活步骤\\n        for (let l = 0; l < stepStationSupArrDis.length; l++) {\\n            var stepArr = stepStationSup.widget.options.steps;\\n            const index = stepArr.findIndex(item => Number(item.title) === stepStationSupArrDis[l].deviceNo);\\n            if (index >= 0) {\\n                stepStationSup.widget.options.steps[index].status = 'finish';\\n            }\\n        }\\n    //***********绑定工位号-激活步骤结束*************